import itertools, json
jobs='ABCDE'
slot={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
rows=[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]
transfer={a:dict(zip(jobs,row)) for a,row in zip(jobs,rows)}
def nominal(p):
 return sum(slot[a][i] for i,a in enumerate(p))+sum(transfer[a][b] for a,b in zip(p,p[1:]))
def incident(p,inc):
 pos={a:p.index(a)+1 for a in jobs}
 if pos['A']>=pos['D']: return None
 if inc=='rain':
  if pos['D']==1 or pos['A']==1: return None
  penalty=6*max(0,pos['C']-1)
 elif inc=='road':
  if pos['C']==4 or pos['E']==2: return None
  penalty=6*max(0,pos['D']-3)
 else:
  if pos['A']==1 or pos['B']==1: return None
  penalty=10*max(0,pos['E']-2)
 return nominal(p)+penalty
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'): continue
 neighbors=[(p,0)]
 for i in range(5):
  for j in range(i+1,5):
   q=list(p);q[i],q[j]=q[j],q[i]
   neighbors.append((tuple(q),1))
 repairs={};costs={}
 for inc in ['rain','road','lift']:
  options=[(v+swap,''.join(q)) for q,swap in neighbors if (v:=incident(q,inc)) is not None]
  if not options: break
  costs[inc],repairs[inc]=min(options)
 else:
  results.append({'roster':''.join(p),'score':nominal(p)+max(costs.values()),'repairs':repairs,'repair_costs':costs})
results.sort(key=lambda x:(x['score'],x['roster']))
best=results[0].copy();best['feasible_count']=len(results);best['next_score']=min(r['score'] for r in results if r['score']>best['score'])
print(json.dumps(best))
print('published nominal',nominal(best['roster']))
print('optima',[(r['roster'],r['score']) for r in results if r['score']==best['score']])

