import itertools,json
jobs='ABCDE';start='AECBD'
S={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
T=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def distance(q):
 perm=[start.index(x) for x in q];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen:seen.add(j);j=perm[j]
 return 5-cycles
classes={k:[] for k in range(3)}
for q in itertools.permutations(jobs):
 d=distance(q)
 if d>2 or q.index('A')>q.index('D') or q[0] in 'AD' or q[3]=='B':continue
 nominal=sum(S[x][i] for i,x in enumerate(q))+sum(T[x][jobs.index(y)] for x,y in zip(q,q[1:]))
 cost=nominal+6*q.index('C')+d+(4 if d==2 else 0)
 classes[d].append((cost,''.join(q)))
best=min(v for values in classes.values() for v in values)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(k):min(v)[0] if v else None for k,v in classes.items()},'feasible_by_swaps':{str(k):len(v) for k,v in classes.items()}}))
print({k:sorted(v) for k,v in classes.items()})
# Independent breadth-first enumeration of actual swaps, recording shortest distance.
dist={start:0};front=[start]
for depth in (1,2):
 nxt=[]
 for p in front:
  for i in range(5):
   for j in range(i+1,5):
    q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
    if q not in dist:dist[q]=depth;nxt.append(q)
 front=nxt
assert all(distance(q)==d for q,d in dist.items())
assert all(q in dist and dist[q]==d for d,vals in classes.items() for _,q in vals)
print('Distance verification passed; reachable counts', {d:sum(v==d for v in dist.values()) for d in range(3)})

